"""Passbands for src/core/sed.js from the SVO Filter Profile Service (Rodrigo, Solano & Bayo 2012; Rodrigo & Solano 2020).

    .venv/bin/python -I tools/stellar/build_passbands.py data-src/svo

Reads the VOTable of each filter (https://svo2.cab.inta-csic.es/theory/fps/fps.php?ID=<facility/filter>, saved as
data-src/svo/<facility>_<filter>.xml) and writes src/core/passbands.js: the response on at most 90 wavelengths
(micron, peak 1), whether the detector counts photons or energy, and the zero point in Jy: the service's Vega zero
point, or 3631 Jy for the surveys whose catalogues are on the AB system (SDSS, Pan-STARRS, APASS's Sloan bands, GALEX).
"""
import glob, json, os, re, sys
import numpy as np

AB = ('SLOAN_', 'PAN-STARRS_', 'Misc_APASS.sdss', 'GALEX_')
NAMES = {'GAIA_GAIA3.G': ('Gaia G', 'gaia'), 'GAIA_GAIA3.Gbp': ('Gaia BP', 'gaia'), 'GAIA_GAIA3.Grp': ('Gaia RP', 'gaia'), '2MASS_2MASS.J': ('2MASS J', '2mass'), '2MASS_2MASS.H': ('2MASS H', '2mass'), '2MASS_2MASS.Ks': ('2MASS Ks', '2mass'),
         'WISE_WISE.W1': ('WISE W1', 'wise'), 'WISE_WISE.W2': ('WISE W2', 'wise'), 'WISE_WISE.W3': ('WISE W3', 'wise'), 'WISE_WISE.W4': ('WISE W4', 'wise'), 'TYCHO_TYCHO.B': ('Tycho BT', 'tycho'), 'TYCHO_TYCHO.V': ('Tycho VT', 'tycho'),
         'GALEX_GALEX.NUV': ('GALEX NUV', 'galex'), 'SLOAN_SDSS.u': ('SDSS u', 'sdss'), 'SLOAN_SDSS.g': ('SDSS g', 'sdss'), 'SLOAN_SDSS.r': ('SDSS r', 'sdss'), 'SLOAN_SDSS.i': ('SDSS i', 'sdss'), 'SLOAN_SDSS.z': ('SDSS z', 'sdss'),
         'PAN-STARRS_PS1.g': ('PS1 g', 'ps1'), 'PAN-STARRS_PS1.r': ('PS1 r', 'ps1'), 'PAN-STARRS_PS1.i': ('PS1 i', 'ps1'), 'PAN-STARRS_PS1.z': ('PS1 z', 'ps1'), 'PAN-STARRS_PS1.y': ('PS1 y', 'ps1'),
         'Generic_Johnson.B': ('Johnson B', 'johnson'), 'Generic_Johnson.V': ('Johnson V', 'johnson'), 'TESS_TESS.Red': ('TESS', 'tess'),
         'Misc_APASS.B': ('APASS B', 'apass'), 'Misc_APASS.V': ('APASS V', 'apass'), 'Misc_APASS.sdss_g': ('APASS g', 'apass'), 'Misc_APASS.sdss_r': ('APASS r', 'apass'), 'Misc_APASS.sdss_i': ('APASS i', 'apass')}
src = sys.argv[1]; out = {}
for key, (name, survey) in NAMES.items():
    s = open(os.path.join(src, key + '.xml')).read()
    par = lambda n: re.search(r'<PARAM name="%s"[^>]*value="([^"]*)"' % n, s).group(1)
    rows = np.array([[float(v) for v in re.findall(r'<TD>([^<]*)</TD>', r)] for r in re.findall(r'<TR>(.*?)</TR>', s, re.S)])
    wl, R = rows[:, 0] * 1e-4, np.maximum(rows[:, 1], 0)
    keep = R > 1e-4 * R.max(); i0, i1 = np.argmax(keep), len(R) - np.argmax(keep[::-1]); wl, R = wl[max(i0 - 1, 0):i1 + 1], R[max(i0 - 1, 0):i1 + 1]
    if len(wl) > 90:   # onto 90 points, keeping the area in each interval
        g = np.linspace(wl[0], wl[-1], 90); cum = np.concatenate([[0], np.cumsum(0.5 * (R[1:] + R[:-1]) * np.diff(wl))]); e = np.concatenate([[g[0]], 0.5 * (g[1:] + g[:-1]), [g[-1]]])
        R = np.diff(np.interp(e, wl, cum)) / np.maximum(np.diff(e), 1e-12); wl = g
    R = R / R.max()
    ab = key.startswith(AB)
    out[name] = dict(id=key.replace('_', '/', 1), survey=survey, system='AB' if ab else 'Vega', zp=3631.0 if ab else round(float(par('ZeroPoint')), 3), photon=par('DetectorType') == '1',
                     wl=[round(float(v), 5) for v in wl], response=[round(float(v), 4) for v in R])
path = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'src', 'core', 'passbands.js')
with open(path, 'w') as f:
    f.write('// Passbands and zero points for src/core/sed.js. Generated by tools/stellar/build_passbands.py from the SVO Filter\n// Profile Service (Rodrigo, Solano & Bayo 2012; Rodrigo & Solano 2020); do not edit.\n//   wl [micron], response (peak 1), photon: the detector counts photons (the weight is response x wavelength),\n//   zp [Jy]: the flux density of magnitude zero (the service\'s Vega zero point, or 3631 Jy on the AB system)\nexport const PASSBANDS = {\n')
    for k, v in out.items(): f.write('  %s: %s,\n' % (json.dumps(k), json.dumps(v, separators=(',', ':'))))
    f.write('};\n')
print(len(out), 'bands ->', os.path.getsize(path), 'bytes')
